	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		DataBreach
	 */
		public DataBreach createDataBreach( CreateDataBreachCommand command ) {

		DataBreach entity = new DataBreach();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setDataBreachId( command.getDataBreachId() );
            entity.setIncidentDate( command.getIncidentDate() );
            entity.setDescription( command.getDescription() );
            entity.setRecordsAffected( command.getRecordsAffected() );
            entity.setNotificationRequired( command.getNotificationRequired() );
            entity.setSeverity( command.getSeverity() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of DataBreach {0} ", entity.toString() );

		return entity;
	}

